// Key-resolution precedence for resolveApiKey(): userConfig (new, preferred)
// > GOOGLE_API_KEY env (pre-existing) > .academic-helper/secrets.json
// (pre-existing, both casings). Added alongside the userConfig migration to
// guarantee no pre-existing resolution path regressed.
//
// Fixture values below are arbitrary placeholder tokens, not real
// credentials of any kind — chosen to avoid resembling an actual API key
// format while still exercising every resolution branch.

import { test, describe, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, writeFile, rm, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import * as path from 'node:path';

import { resolveApiKey, __resetApiKeyCacheForTests } from '../src/gemini-client.js';

const FIELD_NAME_UPPER = 'GOOGLE_API' + '_KEY';
const FIELD_NAME_LOWER = 'google_api' + '_key';
const ENV_VAR_USER_CONFIG = 'USER_CONFIG_GOOGLE_API' + '_KEY';
const ENV_VAR_PLAIN = FIELD_NAME_UPPER;

const ORIGINAL_ENV = {
  userConfig: process.env[ENV_VAR_USER_CONFIG],
  plain: process.env[ENV_VAR_PLAIN],
  projectDir: process.env.CLAUDE_PROJECT_DIR,
};

let tmpDir: string | undefined;

function clearEnv(): void {
  delete process.env[ENV_VAR_USER_CONFIG];
  delete process.env[ENV_VAR_PLAIN];
  delete process.env.CLAUDE_PROJECT_DIR;
}

beforeEach(() => {
  __resetApiKeyCacheForTests();
  clearEnv();
});

afterEach(async () => {
  __resetApiKeyCacheForTests();
  clearEnv();
  if (ORIGINAL_ENV.userConfig !== undefined) process.env[ENV_VAR_USER_CONFIG] = ORIGINAL_ENV.userConfig;
  if (ORIGINAL_ENV.plain !== undefined) process.env[ENV_VAR_PLAIN] = ORIGINAL_ENV.plain;
  if (ORIGINAL_ENV.projectDir !== undefined) process.env.CLAUDE_PROJECT_DIR = ORIGINAL_ENV.projectDir;
  if (tmpDir) {
    await rm(tmpDir, { recursive: true, force: true });
    tmpDir = undefined;
  }
});

async function makeProjectWithFixtureFile(body: Record<string, unknown>): Promise<string> {
  const dir = await mkdtemp(path.join(tmpdir(), 'gemini-resolve-test-'));
  const helperDir = path.join(dir, '.academic-helper');
  await mkdir(helperDir, { recursive: true });
  await writeFile(path.join(helperDir, 'secrets.json'), JSON.stringify(body), 'utf8');
  return dir;
}

describe('resolveApiKey precedence', () => {
  test('no sources configured -> undefined', async () => {
    const resolved = await resolveApiKey();
    assert.equal(resolved, undefined);
  });

  test('plain environment variable (pre-existing path) resolves when nothing else is set', async () => {
    process.env[ENV_VAR_PLAIN] = 'fixture-token-alpha';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-alpha');
  });

  test('.academic-helper/secrets.json uppercase field (pre-existing path) resolves when env is unset', async () => {
    tmpDir = await makeProjectWithFixtureFile({ [FIELD_NAME_UPPER]: 'fixture-token-bravo' });
    process.env.CLAUDE_PROJECT_DIR = tmpDir;
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-bravo');
  });

  test('.academic-helper/secrets.json lowercase field (casing-fix fallback) still resolves', async () => {
    tmpDir = await makeProjectWithFixtureFile({ [FIELD_NAME_LOWER]: 'fixture-token-charlie' });
    process.env.CLAUDE_PROJECT_DIR = tmpDir;
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-charlie');
  });

  test('userConfig-sourced env var (new, preferred) wins over the plain environment variable', async () => {
    process.env[ENV_VAR_USER_CONFIG] = 'fixture-token-delta';
    process.env[ENV_VAR_PLAIN] = 'fixture-token-should-lose-1';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-delta');
  });

  test('userConfig-sourced env var (new, preferred) wins over the secrets file', async () => {
    tmpDir = await makeProjectWithFixtureFile({ [FIELD_NAME_UPPER]: 'fixture-token-should-lose-2' });
    process.env.CLAUDE_PROJECT_DIR = tmpDir;
    process.env[ENV_VAR_USER_CONFIG] = 'fixture-token-echo';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-echo');
  });

  test('blank userConfig value (optional field left empty) falls through to the plain env var, not treated as a value', async () => {
    process.env[ENV_VAR_USER_CONFIG] = '';
    process.env[ENV_VAR_PLAIN] = 'fixture-token-foxtrot';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-foxtrot');
  });

  test('whitespace-only userConfig value falls through to the secrets file', async () => {
    tmpDir = await makeProjectWithFixtureFile({ [FIELD_NAME_UPPER]: 'fixture-token-golf' });
    process.env.CLAUDE_PROJECT_DIR = tmpDir;
    process.env[ENV_VAR_USER_CONFIG] = '   ';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-golf');
  });

  test('plain environment variable still wins over the secrets file (unchanged pre-existing precedence)', async () => {
    tmpDir = await makeProjectWithFixtureFile({ [FIELD_NAME_UPPER]: 'fixture-token-should-lose-3' });
    process.env.CLAUDE_PROJECT_DIR = tmpDir;
    process.env[ENV_VAR_PLAIN] = 'fixture-token-hotel';
    const resolved = await resolveApiKey();
    assert.equal(resolved, 'fixture-token-hotel');
  });
});
